static_assert(kColorLowMidHz == 34 && kColorMidHighHz == 35, "Published split IDs cannot move");
static_assert(kColorEqLowDb == 36 && kColorEqMidDb == 37 && kColorEqHighDb == 38, "Published EQ IDs cannot move");

